contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt);
        uint testBefore = address(this).balance;
        uint cBefore = address(c).balance;

        c.deposit{value: depAmt}(); if (__ESBMC_reverted()) return;

        bool wReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { wReverted = true; } else { wReverted = false; }

        assert(wReverted || (address(this).balance == testBefore && address(c).balance == cBefore));
    }

    receive() external payable {}
}

