// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmt);
        uint testBefore = address(this).balance;
        uint cBefore = address(c).balance;
        try c.deposit{value: depAmt}() {} catch { return; }
        bool wReverted;
        try c.withdrawAll() { wReverted = false; } catch { wReverted = true; }
        assertTrue(wReverted || (address(this).balance == testBefore && address(c).balance == cBefore));
    }

    function testFuzz_run(uint256 depAmt) public {
        _run(depAmt);
    }

    receive() external payable {}
}
